package io.fireflysoftware.common.config.core.authority;

import io.fireflysoftware.common.config.core.authority.impl.TenantResourceBindingGovernedActionsImpl;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingContracts.*;
import io.fireflysoftware.common.config.interfaces.authority.TenantResourceBindingGovernedContracts.*;
import org.fireflyframework.security.api.domain.Decision;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class TenantResourceBindingGovernedActionsTest {
    static final class Fixture {
        final InstitutionAuthorityBudgetTest.Time time=new InstitutionAuthorityBudgetTest.Time();
        final AtomicBoolean allowed=new AtomicBoolean(true);
        final java.util.concurrent.atomic.AtomicReference<Mono<Decision>> policyOverride=new java.util.concurrent.atomic.AtomicReference<>();
        final TenantResourceBindingGovernanceService governance=mock(TenantResourceBindingGovernanceService.class);
        final TenantResourceBindingService controls=mock(TenantResourceBindingService.class);
        final TenantResourceBindingRecoveryReader recovery=mock(TenantResourceBindingRecoveryReader.class);
        final InstitutionAuthorityAuthorization authority=new InstitutionAuthorityAuthorization(()->Mono.just(InstitutionAuthorityBudgetTest.principal(InstitutionAuthorityBudgetTest.T)),(p,a,r,c)->policyOverride.get()==null?Mono.just(allowed.get()?Decision.permit():Decision.deny("current denial")):policyOverride.get(),time,Set.of(InstitutionAuthorityBudgetTest.I),InstitutionAuthorityBudgetTest.T,true);
        final TenantResourceBindingGovernedActions service=new TenantResourceBindingGovernedActionsImpl(authority,governance,controls,recovery);
        final Intent intent=new Intent(Kind.CONTROL,null,null,TenantResourceBindingServiceTest.command(Operation.TENANT_RESOURCE_BINDING_ESTABLISH,0));
        org.fireflyframework.core.transaction.R2dbcOperationBudget budget(){return InstitutionAuthorityBudgetTest.budget(time,800);}
        ActionRequest request(){var prepared=service.prepareIntent(intent,budget()).block();return new ActionRequest(intent,prepared.intentDigest());}
    }
    @Test void intentPreparationIsReadOnlyAndUsesTheSingleOwnerCodec(){var f=new Fixture();var prepared=f.service.prepareIntent(f.intent,f.budget()).block();assertEquals(f.intent.control().actionId(),prepared.actionId());assertEquals(TenantResourceBindingCodec.commandDigest(f.intent.control()),prepared.intentDigest());verifyNoInteractions(f.controls,f.governance,f.recovery);}
    @Test void aCurrentCallerDispatchesTheOriginalControlExactlyOnce(){var f=new Fixture();var request=f.request();var budget=f.budget();var completion=TenantResourceBindingServiceTest.completion(f.intent.control());when(f.controls.establish(f.intent.control(),budget)).thenReturn(Mono.just(completion));var result=f.service.execute(request,budget).block();assertEquals(ActionStatus.COMMITTED,result.status());assertSame(completion,result.completion());assertEquals(request.originalIntentDigest(),result.intentDigest());verify(f.controls).establish(f.intent.control(),budget);verifyNoMoreInteractions(f.controls);verifyNoInteractions(f.governance,f.recovery);}
    @Test void aLostControlResponseKeepsOriginalActionAndDigestWithoutRetry(){var f=new Fixture();var request=f.request();when(f.controls.establish(any(),any())).thenReturn(Mono.error(new IllegalStateException("response lost after dispatch")));var result=f.service.execute(request,f.budget()).block();assertEquals(ActionStatus.OUTCOME_UNKNOWN,result.status());assertEquals(f.intent.control().actionId(),result.actionId());assertEquals(request.originalIntentDigest(),result.intentDigest());assertNull(result.completion());assertNull(result.governanceReceipt());verify(f.controls,times(1)).establish(any(),any());verifyNoMoreInteractions(f.controls);verifyNoInteractions(f.governance,f.recovery);}
    @Test void anEmptyDispatchedResultStillRequiresOriginalActionRecovery(){var f=new Fixture();var request=f.request();when(f.controls.establish(any(),any())).thenReturn(Mono.empty());var result=f.service.execute(request,f.budget()).block();assertNotNull(result);assertEquals(ActionStatus.OUTCOME_UNKNOWN,result.status());assertEquals(request.originalIntentDigest(),result.intentDigest());verify(f.controls,times(1)).establish(any(),any());}
    @Test void currentRefusalBeforeDispatchAcquiresNoBusinessEffect(){var f=new Fixture();var request=f.request();f.allowed.set(false);assertThrows(Exception.class,()->f.service.execute(request,f.budget()).block());verifyNoInteractions(f.controls,f.governance,f.recovery);}
    @Test void finalAuthorityLossCannotTurnACommittedEffectIntoKnownAbsence(){var f=new Fixture();var request=f.request();when(f.controls.establish(any(),any())).thenAnswer(call->{f.allowed.set(false);return Mono.just(TenantResourceBindingServiceTest.completion(f.intent.control()));});var result=f.service.execute(request,f.budget()).block();assertEquals(ActionStatus.COMMITTED_RESPONSE_UNAVAILABLE,result.status());assertEquals(request.originalIntentDigest(),result.intentDigest());assertNull(result.completion());verify(f.controls,times(1)).establish(any(),any());}
    @Test void finalAuthorityStallAfterAnObservedCommitRemainsKnownCommitted(){var f=new Fixture();var request=f.request();when(f.controls.establish(any(),any())).thenAnswer(call->{f.policyOverride.set(Mono.never());return Mono.just(TenantResourceBindingServiceTest.completion(f.intent.control()));});reactor.test.StepVerifier.withVirtualTime(()->f.service.execute(request,f.budget())).thenAwait(java.time.Duration.ofMillis(801)).assertNext(result->{assertEquals(ActionStatus.COMMITTED_RESPONSE_UNAVAILABLE,result.status());assertEquals(request.originalIntentDigest(),result.intentDigest());assertNull(result.completion());}).verifyComplete();verify(f.controls,times(1)).establish(any(),any());}
    @Test void expiredResponseBudgetCannotEraseAnObservedOwnerCommit(){var f=new Fixture();var request=f.request();when(f.controls.establish(any(),any())).thenReturn(Mono.just(TenantResourceBindingServiceTest.completion(f.intent.control())).doOnNext(ignored->f.time.advance(801)));var result=f.service.execute(request,f.budget()).block();assertEquals(ActionStatus.COMMITTED_RESPONSE_UNAVAILABLE,result.status());assertEquals(request.originalIntentDigest(),result.intentDigest());assertNull(result.completion());verify(f.controls,times(1)).establish(any(),any());}
    @Test void replacingTheOriginalDigestIsRejectedBeforeDispatch(){var f=new Fixture();assertThrows(Exception.class,()->f.service.execute(new ActionRequest(f.intent,"f".repeat(64)),f.budget()).block());verifyNoInteractions(f.controls,f.governance,f.recovery);}
    @Test void originalBudgetExpiryBeforeSubscriptionDoesNotDispatch(){var f=new Fixture();var request=f.request();var budget=f.budget();var call=f.service.execute(request,budget);f.time.advance(800);assertThrows(Exception.class,call::block);verifyNoInteractions(f.controls,f.governance,f.recovery);}
    @Test void preparationAndDecisionRemainDistinctRealNativeEffects(){var f=new Fixture();var preparation=new Preparation(UUID.randomUUID(),f.intent.control(),InstitutionAuthorityBudgetTest.NOW.plusSeconds(30).toEpochMilli());var intent=new Intent(Kind.PREPARATION,preparation,null,null);var prepared=f.service.prepareIntent(intent,f.budget()).block();var receipt=new GovernanceReceipt(preparation.actionId(),prepared.intentDigest(),new Proposal(preparation.target().proposalId(),TenantResourceBindingCodec.commandDigest(preparation.target()),"DRAFT",0,preparation.notAfterEpochMillis()),InstitutionAuthorityBudgetTest.NOW.plusMillis(500).toEpochMilli(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());when(f.governance.prepare(any(),any())).thenReturn(Mono.just(receipt));var result=f.service.execute(new ActionRequest(intent,prepared.intentDigest()),f.budget()).block();assertEquals(ActionStatus.COMMITTED,result.status());assertSame(receipt,result.governanceReceipt());assertNull(result.completion());verify(f.governance,times(1)).prepare(eq(preparation),any());verifyNoInteractions(f.controls,f.recovery);}
    @Test void aTypedDecisionDelegatesOnlyTheExistingGovernanceOwner(){var f=new Fixture();var command=f.intent.control();var decision=new DecisionCommand(UUID.randomUUID(),command.definition().resourceTenant(),command.proposalId(),DecisionOperation.APPROVE,1,TenantResourceBindingCodec.commandDigest(command),InstitutionAuthorityBudgetTest.NOW.plusSeconds(30).toEpochMilli());var intent=new Intent(Kind.DECISION,null,decision,null);var prepared=f.service.prepareIntent(intent,f.budget()).block();var receipt=new GovernanceReceipt(decision.actionId(),prepared.intentDigest(),new Proposal(decision.proposalId(),decision.targetDigest(),"APPROVED",2,decision.notAfterEpochMillis()),InstitutionAuthorityBudgetTest.NOW.plusMillis(500).toEpochMilli(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID());when(f.governance.decide(any(),any())).thenReturn(Mono.just(receipt));assertSame(receipt,f.service.execute(new ActionRequest(intent,prepared.intentDigest()),f.budget()).block().governanceReceipt());verify(f.governance).decide(eq(decision),any());verifyNoInteractions(f.controls,f.recovery);}
    @Test void anExplicitRevokeCannotBeRoutedAsEstablish(){var f=new Fixture();var old=f.intent.control();var command=new Command(old.actionId(),old.proposalId(),Operation.TENANT_RESOURCE_BINDING_REVOKE,old.definition(),old.expectedCurrentEligibility(),1);var intent=new Intent(Kind.CONTROL,null,null,command);var prepared=f.service.prepareIntent(intent,f.budget()).block();when(f.controls.revoke(any(),any())).thenReturn(Mono.just(TenantResourceBindingServiceTest.completion(command)));assertEquals(State.REVOKED,f.service.execute(new ActionRequest(intent,prepared.intentDigest()),f.budget()).block().completion().state());verify(f.controls).revoke(eq(command),any());verifyNoMoreInteractions(f.controls);verifyNoInteractions(f.governance,f.recovery);}
    @Test void closedTypedIntentCannotSmuggleAnAlternativeOperation(){var f=new Fixture();assertThrows(IllegalArgumentException.class,()->new Intent(Kind.CONTROL,new Preparation(UUID.randomUUID(),f.intent.control(),1),null,f.intent.control()));assertThrows(IllegalArgumentException.class,()->new Intent(Kind.DECISION,null,null,f.intent.control()));assertThrows(IllegalArgumentException.class,()->new ActionRequest(f.intent,"not-an-owner-digest"));}
    @Test void recoveryDispatchesOnlyTheOriginalReadAndNeverAReplacementMutation(){var f=new Fixture();var request=f.request();var budget=f.budget();var absent=new Recovery(RecoveryStatus.NOT_OBSERVED_AT_THIS_READ,f.intent.control().actionId(),request.originalIntentDigest(),null);when(f.recovery.recover(request,budget)).thenReturn(Mono.just(absent));assertSame(absent,f.service.recover(request,budget).block());verify(f.recovery).recover(request,budget);verifyNoInteractions(f.controls,f.governance);}
}
